mapper.select:
SELECT DISTINCT a.id, a.CODE, a.type, a.create_name, a.create_time, a.update_time, a.`status`, a.warehouse_id, a.shelf_id, a.affirm_time, a.affirm_name, a.note FROM wms_storage_receipt a LEFT JOIN wms_storage_receipt_info b ON a.id = b.storage_receipt_id
a.del_flag = 0
AND a.status = #{dto.status}
and a.code LIKE CONCAT('%',#{dto.code},'%')
and a.type = #{dto.type}
and b.material_name LIKE CONCAT('%',#{dto.materialName},'%')
and b.material_code LIKE CONCAT('%',#{dto.materialCode},'%')
and b.shelf_code LIKE CONCAT('%',#{dto.shelfCode},'%')
and b.shelf_name LIKE CONCAT('%',#{dto.shelfName},'%')
and a.warehouse_id in
#{id}
and b.associated_no in
#{id}
and b.batch like CONCAT('%',#{dto.batch},'%')
and b.case_no like CONCAT('%',#{dto.caseNo},'%')
and a.create_Name like CONCAT('%',#{dto.createName},'%')
and a.affirm_Name like CONCAT('%',#{dto.affirmName},'%')
and a.create_time between #{dto.createStartTime} and #{dto.createEndTime}
and a.affirm_time between #{dto.affirmStartTime} and #{dto.affirmEndTime}
ORDER BY a.update_time DESC

select info.material_id, sum(quantity) as quantity  from wms_storage_receipt wdr join wms_storage_receipt_info info on wdr.id = info.storage_receipt_id
where wdr.del_flag = 0 and info.del_flag = 0

    and wdr.warehouse_id in

        #{id}



    and wdr.affirm_time between #{startTime} and #{endTime}

and wdr.`status` in (1,2,3,5)
group by info.material_id;

mapper.update:
UPDATE wms_storage_receipt
SET status = 1,affirm_name = #{dto.operateName},create_by = #{dto.operateId},create_name = #{dto.operateName},update_by = #{dto.operateId},update_name = #{dto.operateName},source_type = 1,affirm_time = #{dto.operateTime}
WHERE id = #{dto.id}

