where wdr.del_flag = 0 and info.del_flag = 0

    and info.shelf_id in

        #{id}



    and wdr.affirm_time between #{startTime} and #{endTime}

and wdr.`status` in (1,2,3,5)
group by info.material_id;

select info.material_id, sum(quantity) as quantity  from wms_storage_receipt wdr join wms_storage_receipt_info info on wdr.id = info.storage_receipt_id
where wdr.del_flag = 0 and info.del_flag = 0







    and wdr.affirm_time between #{startTime} and #{endTime}


    and info.material_id in

        #{id}


and wdr.`status` in (1,2,3,5)
group by info.material_id;

select info.material_id, info.quantity,info.material_code,wdr.affirm_time from wms_storage_receipt wdr join wms_storage_receipt_info info on wdr.id = info.storage_receipt_id where wdr.del_flag = 0 and info.del_flag = 0
and wdr.affirm_time between #{startTime} and #{endTime}
and wdr.`status` in (1,2,3,5)

SELECT a.material_name, b.type, b.warehouse_id, b.CODE, CASE
WHEN b.STATUS = 0 THEN '已创建' WHEN b.STATUS = 1 THEN '已确认' WHEN b.STATUS = 5 THEN '已冲销' END AS STATUS, count(*) AS caseNum, sum( a.quantity ) AS totalQuantity, CASE
WHEN TIME( b.come_time ) BETWEEN '08:00:00' AND '20:00:00' THEN '白班' ELSE '夜班' END AS classes, group_concat(a.case_no ORDER BY a.case_no SEPARATOR ', ') as caseNo FROM wms_storage_receipt_info a JOIN wms_storage_receipt b ON b.id = a.storage_receipt_id WHERE a.del_flag = 0 and b.del_flag = 0 and a.storage_receipt_id IN ( SELECT id FROM wms_storage_receipt WHERE del_flag = 0 AND STATUS != 5 )
AND b.come_time between #{dto.startTime} and #{dto.endTime}
AND b.status = #{dto.status}
AND a.material_name LIKE CONCAT('%',#{dto.materialName},'%')
AND b.warehouse_id = #{dto.warehouseId}
AND b.type = #{dto.type}
AND TIME(b.come_time) BETWEEN '08:00:00' AND '20:00:00'
AND TIME(b.come_time) NOT BETWEEN '08:00:00' AND '20:00:00'
GROUP BY a.material_name, b.type, b.warehouse_id, b.CODE, CASE
WHEN TIME( b.come_time ) BETWEEN '08:00:00' AND '20:00:00' THEN '白班' ELSE '夜班' END, CASE
WHEN b.STATUS = 0 THEN '已创建' WHEN b.STATUS = 1 THEN '已确认' WHEN b.STATUS = 5 THEN '已冲销' END, b.type ORDER BY b.type;

select a.shelf_name as shelfName, a.material_name as materialName, a.quantity as quantity, a.case_no as caseNo, b.`code` as code, b.STATUS as status, b.create_time as createTime, b.create_name as createName, b.affirm_time as affirmTime, b.affirm_name as affirmName, b.come_time as comeTime from wms_storage_receipt_info a JOIN wms_storage_receipt b on b.id = a.storage_receipt_id where a.storage_receipt_id in ( SELECT id from wms_storage_receipt where del_flag = 0 AND status != 5)
AND b.come_time between #{dto.startTime} and #{dto.endTime}
and a.case_no in
#{caseNo}

